/**
 * Highlight overlay management for XPath Forte
 *
 * Handles element highlighting during inspection and test evaluation.
 */
import { getUIRoot } from './uiRoot';
let highlightOverlay = null;
let testHighlights = [];
export const createHighlightOverlay = () => {
    const overlay = document.createElement('div');
    overlay.className = 'xpath-finder-highlight';
    const cursorIndicator = document.createElement('div');
    cursorIndicator.className = 'xpath-finder-cursor-indicator';
    overlay.appendChild(cursorIndicator);
    return overlay;
};
export const getHighlightOverlay = () => highlightOverlay;
export const setHighlightOverlay = (overlay) => { highlightOverlay = overlay; };
export const ensureHighlightOverlay = () => {
    // isConnected guards against a stale reference after the shared host was torn
    // down (teardownUIRoot) — recreate the overlay inside the fresh root.
    if (!highlightOverlay || !highlightOverlay.isConnected) {
        highlightOverlay = createHighlightOverlay();
        getUIRoot().appendChild(highlightOverlay);
    }
    return highlightOverlay;
};
export const updateHighlightPosition = (element, cursorX, cursorY) => {
    const overlay = ensureHighlightOverlay();
    const rect = element.getBoundingClientRect();
    overlay.style.top = `${window.scrollY + rect.top}px`;
    overlay.style.left = `${window.scrollX + rect.left}px`;
    overlay.style.width = `${rect.width}px`;
    overlay.style.height = `${rect.height}px`;
    overlay.style.display = 'block';
    const indicator = overlay.querySelector('.xpath-finder-cursor-indicator');
    if (indicator && typeof cursorX === 'number' && typeof cursorY === 'number') {
        // The indicator is positioned relative to the overlay. Both the cursor
        // coords and rect.top/left are viewport-relative, so the offset within the
        // overlay is a plain difference — adding scroll here shifted the dot off
        // the cursor by exactly the scroll distance on scrolled pages.
        indicator.setAttribute('style', `
      display: block;
      position: absolute;
      top: ${cursorY - rect.top}px;
      left: ${cursorX - rect.left}px;
    `);
    }
    else if (indicator) {
        indicator.setAttribute('style', 'display: none;');
    }
};
export const removeHighlight = () => {
    if (highlightOverlay) {
        highlightOverlay.style.display = 'none';
    }
};
export const clearTestHighlights = () => {
    testHighlights.forEach(el => el.remove());
    testHighlights = [];
};
export const highlightTestMatches = (elements) => {
    clearTestHighlights();
    elements.forEach(el => {
        const rect = el.getBoundingClientRect();
        const overlay = document.createElement('div');
        overlay.className = 'xpath-finder-test-highlight';
        overlay.style.top = `${window.scrollY + rect.top}px`;
        overlay.style.left = `${window.scrollX + rect.left}px`;
        overlay.style.width = `${rect.width}px`;
        overlay.style.height = `${rect.height}px`;
        getUIRoot().appendChild(overlay);
        testHighlights.push(overlay);
    });
};
