/**
 * CSS Selector Generators for XPath Forte
 *
 * Generates CSS selectors alongside XPaths for automation testing.
 */
import { containsNumericComponent, isTransientStateClass } from './xpathGenerators';
/**
 * Escapes a string for use as a CSS identifier (ID or class name).
 *
 * Why CSS.escape (not a homemade regex): leading digits, hyphens, control
 * characters, and astral-plane Unicode all need different escape forms per
 * the CSSOM spec. A handwritten regex that "looks right" silently emits
 * invalid selectors (e.g. `#1submit` for an HTML5-valid id="1submit"), which
 * the uniqueness check then drops — leaving the user with only fragile
 * fallbacks and no idea why. CSS.escape is in every browser that supports
 * extensions; the regex fallback covers jsdom only.
 */
const escapeCSSString = (str) => {
    if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
        return CSS.escape(str);
    }
    // Fallback for environments without CSS.escape (older jsdom). Order matters:
    // do the punctuation escape FIRST on the original string, then prepend the
    // unicode-escape for a leading digit. Doing it the other way escapes the
    // backslash we just inserted, breaking the unicode-escape syntax.
    const punctEscaped = str.replace(/([!"#$%&'()*+,.\/:;<=>?@[\\\]^`{|}~ ])/g, '\\$1');
    if (/^\d/.test(str)) {
        return `\\3${str[0]} ${punctEscaped.slice(1)}`;
    }
    if (/^-\d/.test(str)) {
        return `-\\3${str[1]} ${punctEscaped.slice(2)}`;
    }
    return punctEscaped;
};
/**
 * Escapes a value for use inside a CSS attribute selector: [attr="value"]
 * Handles quotes, backslashes, and control characters that would break the
 * selector syntax (CSS strings may not contain unescaped newlines, etc.).
 */
const escapeCSSAttrValue = (str) => {
    return str
        .replace(/\\/g, '\\\\')
        .replace(/"/g, '\\"')
        // eslint-disable-next-line no-control-regex
        .replace(/[\x00-\x1f\x7f]/g, ch => `\\${ch.charCodeAt(0).toString(16)} `);
};
/**
 * Checks if a CSS selector uniquely matches the target element in the document.
 * Returns 'unique' (1 match = target), 'valid' (target is among matches), or 'invalid'.
 */
const isExtensionEl = (el) => !!el.closest('#xpath-forte-host') ||
    el.classList.contains('xpath-finder-highlight') ||
    el.classList.contains('xpath-finder-test-highlight') ||
    el.classList.contains('xpath-finder-cursor-indicator');
const checkCSSUniqueness = (selector, element) => {
    try {
        // Validate within the element's own root. document.querySelectorAll cannot
        // see into shadow DOM, so validating a shadow-tree element against the
        // document dropped EVERY candidate — and with them the piercing (>>>)
        // selectors the panel builds on top of these results.
        const rootNode = element.getRootNode();
        const scope = rootNode instanceof ShadowRoot ? rootNode : document;
        const matches = scope.querySelectorAll(selector);
        // Filter out extension UI elements
        const filtered = [];
        matches.forEach(el => {
            if (!isExtensionEl(el)) {
                filtered.push(el);
            }
        });
        if (filtered.length === 0)
            return 'invalid';
        if (filtered.length === 1 && filtered[0] === element)
            return 'unique';
        if (filtered.includes(element))
            return 'valid';
        return 'invalid';
    }
    catch (_a) {
        return 'invalid';
    }
};
/**
 * Generates CSS selectors for a given element.
 * All selectors are validated — only those that actually match the target are returned.
 */
export const generateCSSSelectors = (element) => {
    if (!element)
        return [];
    const candidates = [];
    const tagName = element.tagName.toLowerCase();
    // ID-based
    if (element.id && !containsNumericComponent(element.id)) {
        candidates.push({
            pattern: 'ID Selector',
            selector: `#${escapeCSSString(element.id)}`,
            isValid: true,
            category: 'ID-based',
        });
        candidates.push({
            pattern: 'Tag with ID',
            selector: `${tagName}#${escapeCSSString(element.id)}`,
            isValid: true,
            category: 'ID-based',
        });
    }
    // Class-based — emit progressively narrower variants so Tailwind-heavy
    // elements (5-15+ utility classes) still produce a usable selector when
    // ONE class changes in production. The uniqueness check at the end drops
    // any variant that doesn't actually match the target.
    if (element.className && typeof element.className === 'string') {
        const classes = element.className.split(/\s+/).filter(cls => cls && !containsNumericComponent(cls) && !isTransientStateClass(cls));
        if (classes.length > 0) {
            // Full multi-class — most specific; survives reorderings but breaks on
            // any single class removal.
            candidates.push({
                pattern: 'Tag with Class',
                selector: `${tagName}.${classes.map(c => escapeCSSString(c)).join('.')}`,
                isValid: true,
                category: 'Class-based',
            });
            // Single-class variants — give the user a fallback that survives N-1
            // class churns. Limited to first 3 to avoid noise on 15-class elements.
            const singleClassLimit = Math.min(classes.length, 3);
            for (let i = 0; i < singleClassLimit; i++) {
                candidates.push({
                    pattern: classes.length === 1 ? 'Class Selector' : `Single Class (${classes[i]})`,
                    selector: `${tagName}.${escapeCSSString(classes[i])}`,
                    isValid: true,
                    category: 'Class-based',
                });
            }
            // Two-class combo when there are 3+ — middle ground between full and single.
            if (classes.length >= 3) {
                candidates.push({
                    pattern: 'Two-Class Combo',
                    selector: `${tagName}.${escapeCSSString(classes[0])}.${escapeCSSString(classes[1])}`,
                    isValid: true,
                    category: 'Class-based',
                });
            }
        }
    }
    // data-testid / data-test / data-cy / data-qa
    const testAttrs = ['data-testid', 'data-test', 'data-test-id', 'data-cy', 'data-qa', 'data-automation', 'data-auto'];
    for (const attrName of testAttrs) {
        const val = element.getAttribute(attrName);
        if (val) {
            candidates.push({
                pattern: `${attrName} Selector`,
                selector: `[${attrName}="${escapeCSSAttrValue(val)}"]`,
                isValid: true,
                category: 'Test ID',
            });
            break;
        }
    }
    // Name attribute
    const name = element.getAttribute('name');
    if (name && !containsNumericComponent(name)) {
        candidates.push({
            pattern: 'Name Attribute',
            selector: `${tagName}[name="${escapeCSSAttrValue(name)}"]`,
            isValid: true,
            category: 'Attribute-based',
        });
    }
    // Placeholder
    const placeholder = element.getAttribute('placeholder');
    if (placeholder && !containsNumericComponent(placeholder)) {
        candidates.push({
            pattern: 'Placeholder',
            selector: `${tagName}[placeholder="${escapeCSSAttrValue(placeholder)}"]`,
            isValid: true,
            category: 'Attribute-based',
        });
    }
    // Type attribute — only useful when combined with other qualifiers, skip alone
    const type = element.getAttribute('type');
    if (type && name && !containsNumericComponent(name)) {
        candidates.push({
            pattern: 'Type + Name',
            selector: `${tagName}[type="${escapeCSSAttrValue(type)}"][name="${escapeCSSAttrValue(name)}"]`,
            isValid: true,
            category: 'Multi-attribute',
        });
    }
    // Role
    const role = element.getAttribute('role');
    if (role && !containsNumericComponent(role)) {
        candidates.push({
            pattern: 'Role Attribute',
            selector: `${tagName}[role="${escapeCSSAttrValue(role)}"]`,
            isValid: true,
            category: 'Attribute-based',
        });
    }
    // Aria-label
    const ariaLabel = element.getAttribute('aria-label');
    if (ariaLabel && !containsNumericComponent(ariaLabel)) {
        candidates.push({
            pattern: 'Aria Label',
            selector: `[aria-label="${escapeCSSAttrValue(ariaLabel)}"]`,
            isValid: true,
            category: 'Accessibility',
        });
    }
    // Parent > child — qualified on both sides
    const parent = element.parentElement;
    if (parent) {
        // Build a qualified child suffix
        let childQualifier = tagName;
        const stableClasses = (element.className && typeof element.className === 'string')
            ? element.className.split(/\s+/).filter(cls => cls && !containsNumericComponent(cls) && !isTransientStateClass(cls))
            : [];
        if (stableClasses.length > 0) {
            childQualifier = `${tagName}.${escapeCSSString(stableClasses[0])}`;
        }
        else if (name && !containsNumericComponent(name)) {
            childQualifier = `${tagName}[name="${escapeCSSAttrValue(name)}"]`;
        }
        if (parent.id && !containsNumericComponent(parent.id)) {
            candidates.push({
                pattern: 'Parent ID > Child',
                selector: `#${escapeCSSString(parent.id)} > ${childQualifier}`,
                isValid: true,
                category: 'Structural',
            });
        }
        if (parent.className && typeof parent.className === 'string') {
            const parentClasses = parent.className.split(/\s+/).filter(cls => cls && !containsNumericComponent(cls) && !isTransientStateClass(cls));
            if (parentClasses.length > 0) {
                const parentTag = parent.tagName.toLowerCase();
                candidates.push({
                    pattern: 'Parent Class > Child',
                    selector: `${parentTag}.${escapeCSSString(parentClasses[0])} > ${childQualifier}`,
                    isValid: true,
                    category: 'Structural',
                });
            }
        }
        // Structural pseudo-classes — more stable than nth-of-type for certain cases
        const siblings = Array.from(parent.children);
        const sameTagSiblings = siblings.filter(s => s.tagName === element.tagName);
        if (sameTagSiblings.length === 1) {
            // Only child of its type — :only-of-type is very stable
            let parentSel = parent.tagName.toLowerCase();
            if (parent.id && !containsNumericComponent(parent.id)) {
                parentSel = `#${escapeCSSString(parent.id)}`;
            }
            else if (parent.className && typeof parent.className === 'string') {
                const pc = parent.className.split(/\s+/).filter(cls => cls && !containsNumericComponent(cls) && !isTransientStateClass(cls));
                if (pc.length > 0)
                    parentSel = `${parent.tagName.toLowerCase()}.${escapeCSSString(pc[0])}`;
            }
            candidates.push({
                pattern: 'Only of Type',
                selector: `${parentSel} > ${tagName}:only-of-type`,
                isValid: true,
                category: 'Structural',
            });
        }
        else if (sameTagSiblings.length > 1) {
            const index = sameTagSiblings.indexOf(element) + 1;
            let parentSel = parent.tagName.toLowerCase();
            if (parent.id && !containsNumericComponent(parent.id)) {
                parentSel = `#${escapeCSSString(parent.id)}`;
            }
            else if (parent.className && typeof parent.className === 'string') {
                const pc = parent.className.split(/\s+/).filter(cls => cls && !containsNumericComponent(cls) && !isTransientStateClass(cls));
                if (pc.length > 0)
                    parentSel = `${parent.tagName.toLowerCase()}.${escapeCSSString(pc[0])}`;
            }
            // first-of-type / last-of-type are more stable than nth-of-type
            if (index === 1) {
                candidates.push({
                    pattern: 'First of Type',
                    selector: `${parentSel} > ${tagName}:first-of-type`,
                    isValid: true,
                    category: 'Structural',
                });
            }
            else if (index === sameTagSiblings.length) {
                candidates.push({
                    pattern: 'Last of Type',
                    selector: `${parentSel} > ${tagName}:last-of-type`,
                    isValid: true,
                    category: 'Structural',
                });
            }
            candidates.push({
                pattern: 'nth-of-type',
                selector: `${parentSel} > ${tagName}:nth-of-type(${index})`,
                isValid: true,
                category: 'Position-based',
            });
        }
    }
    // Multi-attribute
    const attrs = Array.from(element.attributes)
        .filter(a => !['class', 'style', 'id'].includes(a.name) && !containsNumericComponent(a.value))
        .slice(0, 2);
    if (attrs.length >= 2) {
        candidates.push({
            pattern: 'Multi-Attribute',
            selector: `${tagName}[${attrs[0].name}="${escapeCSSAttrValue(attrs[0].value)}"][${attrs[1].name}="${escapeCSSAttrValue(attrs[1].value)}"]`,
            isValid: true,
            category: 'Multi-attribute',
        });
    }
    // Validate all candidates — only return those that actually match the target element
    const results = [];
    const seen = new Set();
    for (const candidate of candidates) {
        if (seen.has(candidate.selector))
            continue;
        seen.add(candidate.selector);
        const uniqueness = checkCSSUniqueness(candidate.selector, element);
        if (uniqueness !== 'invalid') {
            results.push(candidate);
        }
    }
    return results;
};
