/**
 * Shared Shadow DOM root for ALL of XPath Forte's injected UI — the panel AND
 * every overlay (highlight, test-highlight, cursor indicator, session indicator).
 *
 * Why one CLOSED shadow root:
 * Previously the panel lived in an open shadow root while the highlight/session
 * overlays were appended straight to document.body. Those light-DOM overlay nodes
 * (and, for tools that pierce shadow DOM, the panel) could be matched by a
 * generated selector when the user pasted it into Chrome DevTools' Ctrl+F or ran
 * it via $x()/Selenium in the same tab — inflating the match count (e.g. showing
 * "2" for a unique element). Housing everything in a single closed shadow root
 * keeps our nodes out of the light-DOM document entirely: document.evaluate /
 * querySelectorAll / $x() cannot reach a closed root, so a copied selector only
 * ever matches real page elements.
 *
 * Positioning: the host is pinned at the document origin (top:0,left:0) and is
 * positioned, so the absolutely-positioned overlays — which set their top/left
 * from window.scroll + getBoundingClientRect() — render exactly where they did
 * in document.body. The host carries `all:initial` (no transform/filter/contain),
 * so it does NOT create a containing block for position:fixed descendants; the
 * panel and session indicator stay viewport-anchored.
 */
const HOST_ID = 'xpath-forte-host';
let host = null;
let root = null;
/** Lazily creates the shared host + closed shadow root and returns the root. */
export const getUIRoot = () => {
    if (root)
        return root;
    host = document.createElement('div');
    host.id = HOST_ID;
    host.dataset.xpathForte = 'true';
    host.style.cssText =
        'all:initial; position:absolute; top:0; left:0; width:0; height:0; overflow:visible; z-index:2147483647;';
    // Closed: external/page code and document-scoped selector search cannot reach in.
    root = host.attachShadow({ mode: 'closed' });
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = chrome.runtime.getURL('content.css');
    root.appendChild(link);
    document.body.appendChild(host);
    return root;
};
/** Returns the shared root only if it already exists (no creation side-effect). */
export const getUIRootIfPresent = () => root;
/** Whether the shared host is currently mounted. */
export const hasUIHost = () => !!host;
/** Removes the shared host — and with it the panel and every overlay at once. */
export const teardownUIRoot = () => {
    if (host)
        host.remove();
    host = null;
    root = null;
};
