/**
 * Locator Stability Scorer for XPath Forte
 *
 * Rates locator stability from 0-100 based on the selector strategy used.
 * Higher scores indicate more resilient, maintenance-friendly selectors.
 */
import { containsNumericComponent } from '../generators/xpathGenerators';
/**
 * Scores an XPath expression for stability
 */
export const scoreXPath = (xpath, category) => {
    let score = 50; // baseline
    // Category-based scoring
    const categoryScores = {
        'Best Match': 92,
        'Unique/ID-based': 90,
        'Test ID': 95,
        'Attribute-based': 70,
        'Text-based': 55,
        'Class-based': 60,
        'Multi-attribute': 75,
        'Sibling/Following': 45,
        'Relation-based': 45,
        'Parent/Ancestor': 50,
        'Ancestor-based': 50,
        'Context-aware': 65,
        'Context-based': 65,
        'Structural': 60,
        'Collection/Index-based': 35,
        'Position-based': 25,
        'Sibling-based': 40,
        'CSS-like Path': 45,
        'Accessibility': 80,
    };
    if (categoryScores[category] !== undefined) {
        score = categoryScores[category];
    }
    // Adjust based on XPath characteristics. ID boost is conditional: long
    // hash-shaped ids (e.g. "_ngcontent-c5") shouldn't get the same trust as a
    // human-authored id. We extract the @id="..." value and demote if it looks
    // dynamic.
    const idMatch = xpath.match(/@id=["']([^"']+)["']/);
    if (idMatch) {
        const idVal = idMatch[1];
        // Reuse the generators' framework-aware dynamic-value detector so a short
        // generated id (_ngcontent-c5, j_idt88, jss123) isn't trusted like a
        // human-authored one — the length/hex heuristics alone miss those.
        const looksDynamic = idVal.length > 32 || /[a-f0-9]{8,}/i.test(idVal) || containsNumericComponent(idVal);
        score = Math.max(score, looksDynamic ? 65 : 85);
    }
    if (xpath.includes('data-testid') || xpath.includes('data-test') || xpath.includes('data-cy'))
        score = Math.max(score, 92);
    if (xpath.includes('@name='))
        score = Math.max(score, 75);
    if (xpath.includes('@aria-label='))
        score = Math.max(score, 78);
    if (xpath.includes('@role='))
        score = Math.max(score, 72);
    if (xpath.includes('@placeholder='))
        score = Math.max(score, 68);
    // Penalize fragile patterns — apply the strictest cap among all matched penalties
    let penaltyCap = Infinity;
    const slashCount = (xpath.match(/\//g) || []).length;
    if (slashCount > 6)
        penaltyCap = Math.min(penaltyCap, 35);
    if (xpath.includes('[position()') || /\[\d+\]/.test(xpath))
        penaltyCap = Math.min(penaltyCap, 40);
    if (xpath.includes('following-sibling') || xpath.includes('preceding-sibling'))
        penaltyCap = Math.min(penaltyCap, 50);
    // Partial TEXT matches (starts-with / contains on the text node) are looser
    // than an exact normalize-space(.)= match: a sibling whose text merely begins
    // with or contains the same string also matches. Note: this deliberately does
    // NOT catch the word-bounded class idiom contains(concat(" ", normalize-space(@class)...).
    if (xpath.includes('starts-with(normalize-space') || xpath.includes('contains(normalize-space(.')) {
        penaltyCap = Math.min(penaltyCap, 50);
    }
    if (xpath.startsWith('/html/body'))
        penaltyCap = Math.min(penaltyCap, 20);
    if (penaltyCap < Infinity)
        score = Math.min(score, penaltyCap);
    // Clamp
    score = Math.max(0, Math.min(100, score));
    return {
        score,
        level: score >= 70 ? 'high' : score >= 45 ? 'medium' : 'low',
        label: score >= 70 ? 'Stable' : score >= 45 ? 'Moderate' : 'Fragile',
    };
};
/**
 * Scores a CSS selector for stability
 */
export const scoreCSSSelector = (selector, category) => {
    let score = 50;
    const categoryScores = {
        'ID-based': 90,
        'Test ID': 95,
        'Class-based': 65,
        'Attribute-based': 72,
        'Accessibility': 80,
        'Structural': 50,
        'Position-based': 30,
        'Multi-attribute': 75,
    };
    if (categoryScores[category] !== undefined) {
        score = categoryScores[category];
    }
    // Adjust based on CSS characteristics
    if (selector.startsWith('#'))
        score = Math.max(score, 88);
    if (selector.includes('data-testid') || selector.includes('data-test') || selector.includes('data-cy'))
        score = Math.max(score, 92);
    if (selector.includes('[name='))
        score = Math.max(score, 74);
    if (selector.includes('[aria-label='))
        score = Math.max(score, 78);
    // Penalize fragile patterns
    if (selector.includes('nth-of-type') || selector.includes('nth-child'))
        score = Math.min(score, 40);
    if ((selector.match(/>/g) || []).length > 3)
        score = Math.min(score, 35);
    score = Math.max(0, Math.min(100, score));
    return {
        score,
        level: score >= 70 ? 'high' : score >= 45 ? 'medium' : 'low',
        label: score >= 70 ? 'Stable' : score >= 45 ? 'Moderate' : 'Fragile',
    };
};
/**
 * Scores a Playwright locator for stability
 */
export const scorePlaywrightLocator = (locator, category) => {
    let score = 50;
    const categoryScores = {
        'Test ID': 95,
        'Role-based': 90,
        'Label': 88,
        'Attribute-based': 75,
        'Text-based': 70,
        'Alt Text': 72,
        'Title': 68,
    };
    if (categoryScores[category] !== undefined) {
        score = categoryScores[category];
    }
    // Boost for specific patterns
    if (locator.includes('getByTestId'))
        score = Math.max(score, 93);
    if (locator.includes('getByRole') && locator.includes('name:'))
        score = Math.max(score, 88);
    if (locator.includes('getByLabel'))
        score = Math.max(score, 85);
    // Slight penalty for partial text match (no exact: true)
    if (locator.includes('getByText') && !locator.includes('exact'))
        score = Math.min(score, 60);
    score = Math.max(0, Math.min(100, score));
    return {
        score,
        level: score >= 70 ? 'high' : score >= 45 ? 'medium' : 'low',
        label: score >= 70 ? 'Stable' : score >= 45 ? 'Moderate' : 'Fragile',
    };
};
/** Checks if a node is inside the extension's own UI (shadow host or highlight overlays) */
const isInsideExtension = (node) => {
    const el = node instanceof Element ? node : node.parentElement;
    if (!el)
        return false;
    return !!el.closest('#xpath-forte-host') ||
        el.classList.contains('xpath-finder-highlight') ||
        el.classList.contains('xpath-finder-test-highlight') ||
        el.classList.contains('xpath-finder-cursor-indicator');
};
/**
 * Gets the match count for an XPath in the document (excluding the extension panel)
 */
export const getXPathMatchCount = (xpath) => {
    try {
        const result = document.evaluate(xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
        let count = 0;
        for (let i = 0; i < result.snapshotLength; i++) {
            const node = result.snapshotItem(i);
            if (node && !isInsideExtension(node))
                count++;
        }
        return count;
    }
    catch (_a) {
        return -1; // invalid xpath
    }
};
/**
 * Gets the match count for a CSS selector in the document (excluding the extension panel)
 */
export const getCSSMatchCount = (selector) => {
    try {
        let count = 0;
        document.querySelectorAll(selector).forEach(el => {
            if (!isInsideExtension(el))
                count++;
        });
        return count;
    }
    catch (_a) {
        return -1;
    }
};
